    "pasos": [
      {
        "id": "paso-1",
        "titulo": "1. Tensión de nodo VA",
        "pregunta": "Calcule la tensión $V_A$ en el nodo central.",
        "pistas": [
          "Pista 1 (Concepto): Aplique LCK en el nodo A sumando las corrientes salientes.",
          "Pista 2 (Ecuación): $\\frac{V_A - 24}{6} + \\frac{V_A}{12} + \\frac{V_A - 6}{4} = 0$.",
          "Pista 3 (Cálculo): Multiplique toda la ecuación por el MCM 12: $2(V_A - 24) + V_A + 3(V_A - 6) = 0 \\implies 2V_A - 48 + V_A + 3V_A - 18 = 0 \\implies 6V_A = 66 \\implies V_A = 11\\text{ V}$."
        ],
        "explicacion": "Planteo de LCK en el nodo $V_A$:\\n$\\frac{V_A - 24}{6} + \\frac{V_A}{12} + \\frac{V_A - 6}{4} = 0$\\nMultiplicando por 12:\\n$2(V_A - 24) + V_A + 3(V_A - 6) = 0$\\n$2V_A - 48 + V_A + 3V_A - 18 = 0$\\n$6 V_A = 66 \\implies V_A = 11.0\\text{ V}$.",
        "tipoRespuesta": "numerica",
        "unidad": "V",
        "solucion": 11.0,
        "tolerancia": 0.05,
        "simbolo": "V_A",
        "valorEsperado": 11.0,
        "explicacionPaso": "Planteo de LCK en el nodo $V_A$:\\n$\\frac{V_A - 24}{6} + \\frac{V_A}{12} + \\frac{V_A - 6}{4} = 0$\\nMultiplicando por 12:\\n$2(V_A - 24) + V_A + 3(V_A - 6) = 0$\\n$2V_A - 48 + V_A + 3V_A - 18 = 0$\\n$6 V_A = 66 \\implies V_A = 11.0\\text{ V}$."
      },
      {
        "id": "paso-2",
        "titulo": "2. Corriente en R2",
        "pregunta": "Calcule la corriente $I_{R2}$ que circula hacia masa por $R_2$ (en Amperes).",
        "pistas": [
          "Pista 1: La tensión en extremos de $R_2$ es exactamente la tensión nodal $V_A$.",
          "Pista 2: Aplique la Ley de Ohm: $I_{R2} = V_A / R_2$.",
          "Pista 3: $11\\text{ V} / 12\\,\\Omega = 0.917\\text{ A}$."
        ],
        "explicacion": "$I_{R2} = \\frac{V_A}{R_2} = \\frac{11\\text{ V}}{12\\,\\Omega} \\approx 0.917\\text{ A}$ (917 mA).",
        "tipoRespuesta": "numerica",
        "unidad": "A",
        "solucion": 0.917,
        "tolerancia": 0.05,
        "simbolo": "I_{R2}",
        "valorEsperado": 0.917,
        "explicacionPaso": "$I_{R2} = \\frac{V_A}{R_2} = \\frac{11\\text{ V}}{12\\,\\Omega} \\approx 0.917\\text{ A}$ (917 mA)."
      }
    ]
