    "pasos": [
      {
        "id": "paso-1",
        "titulo": "1. Tensión de Thévenin (Voc)",
        "pregunta": "Calcule la tensión a circuito abierto $V_{th}$ entre las terminales A y B.",
        "pistas": [
          "Pista 1: A circuito abierto, ninguna corriente fluye a través de $R_3$.",
          "Pista 2: Por tanto, la tensión $V_{th}$ es la caída sobre $R_2$ en el divisor formado por $R_1$ y $R_2$.",
          "Pista 3: $V_{th} = 24\\text{ V} \\cdot \\frac{12}{6 + 12} = 24 \\cdot \\frac{12}{18} = 16\\text{ V}$."
        ],
        "explicacion": "Al estar los terminales A-B abiertos, por $R_3$ no circula corriente ($I_{R3} = 0$), de modo que la caída en $R_3$ es nula. Por lo tanto, $V_{th} = V_{R2} = V_S \\cdot \\frac{R_2}{R_1 + R_2} = 24\\text{ V} \\cdot \\frac{12}{18} = 16.0\\text{ V}$.",
        "tipoRespuesta": "numerica",
        "unidad": "V",
        "solucion": 16.0,
        "tolerancia": 0.05,
        "simbolo": "V_{th}",
        "valorEsperado": 16.0,
        "explicacionPaso": "Al estar los terminales A-B abiertos, por $R_3$ no circula corriente ($I_{R3} = 0$), de modo que la caída en $R_3$ es nula. Por lo tanto, $V_{th} = V_{R2} = V_S \\cdot \\frac{R_2}{R_1 + R_2} = 24\\text{ V} \\cdot \\frac{12}{18} = 16.0\\text{ V}$."
      },
      {
        "id": "paso-2",
        "titulo": "2. Resistencia de Thévenin (Rth)",
        "pregunta": "Determine la resistencia equivalente de Thévenin $R_{th}$ vista desde A-B.",
        "pistas": [
          "Pista 1: Pasive la fuente independiente de tensión $V_S$ sustituyéndola por un cortocircuito a masa.",
          "Pista 2: Desde los bornes A-B se ve $R_3$ en serie con el paralelo $(R_1 \\parallel R_2)$.",
          "Pista 3: $R_1 \\parallel R_2 = (6 \\cdot 12) / (6 + 12) = 72 / 18 = 4\\,\\Omega$. Luego $R_{th} = 4 + 4 = 8\\,\\Omega$."
        ],
        "explicacion": "Pasivando la fuente $V_S$ (cortocircuito): $R_1$ queda en paralelo con $R_2$: $R_p = \\frac{6 \\cdot 12}{6 + 12} = 4\\,\\Omega$. Sumando la resistencia serie $R_3$: $R_{th} = R_3 + R_p = 4 + 4 = 8.0\\,\\Omega$.",
        "tipoRespuesta": "numerica",
        "unidad": "Ω",
        "solucion": 8.0,
        "tolerancia": 0.05,
        "simbolo": "R_{th}",
        "valorEsperado": 8.0,
        "explicacionPaso": "Pasivando la fuente $V_S$ (cortocircuito): $R_1$ queda en paralelo con $R_2$: $R_p = \\frac{6 \\cdot 12}{6 + 12} = 4\\,\\Omega$. Sumando la resistencia serie $R_3$: $R_{th} = R_3 + R_p = 4 + 4 = 8.0\\,\\Omega$."
      },
      {
        "id": "paso-3",
        "titulo": "3. Corriente sobre carga RL",
        "pregunta": "Calcule la corriente $I_L$ que se establece al conectar $R_L = 8\\,\\Omega$ entre A y B.",
        "pistas": [
          "Pista 1: Emplee el circuito equivalente Thévenin obtenido: una fuente $V_{th}$ alimentando a $R_{th} + R_L$.",
          "Pista 2: $I_L = \\frac{V_{th}}{R_{th} + R_L}$.",
          "Pista 3: $16\\text{ V} / (8\\,\\Omega + 8\\,\\Omega) = 16 / 16 = 1.0\\text{ A}$."
        ],
        "explicacion": "Aplicando la Ley de Ohm sobre el equivalente Thévenin: $I_L = \\frac{V_{th}}{R_{th} + R_L} = \\frac{16\\text{ V}}{8\\,\\Omega + 8\\,\\Omega} = 1.0\\text{ A}$.",
        "tipoRespuesta": "numerica",
        "unidad": "A",
        "solucion": 1.0,
        "tolerancia": 0.05,
        "simbolo": "I_L",
        "valorEsperado": 1.0,
        "explicacionPaso": "Aplicando la Ley de Ohm sobre el equivalente Thévenin: $I_L = \\frac{V_{th}}{R_{th} + R_L} = \\frac{16\\text{ V}}{8\\,\\Omega + 8\\,\\Omega} = 1.0\\text{ A}$."
      }
    ]
