    "pasos": [
      {
        "id": "paso-1",
        "titulo": "1. Corriente en la carga",
        "pregunta": "Calcule la corriente $I_L$ que demanda la carga $R_L$ (en mA).",
        "pistas": [
          "Pista 1: Al estar en la zona de ruptura Zener, la tensión sobre la carga es $V_Z = 6.8\\text{ V}$.",
          "Pista 2: Aplique la Ley de Ohm: $I_L = V_Z / R_L$.",
          "Pista 3: $6.8\\text{ V} / 1\\text{ k}\\Omega = 6.8\\text{ mA}$."
        ],
        "explicacion": "Como el Zener mantiene fijada la tensión en bornes de la carga en $V_Z$:\\n$I_L = \\frac{V_Z}{R_L} = \\frac{6.8\\text{ V}}{1000\\,\\Omega} = 6.8\\text{ mA}$.",
        "tipoRespuesta": "numerica",
        "unidad": "mA",
        "solucion": 6.8,
        "tolerancia": 0.05,
        "simbolo": "I_L",
        "valorEsperado": 6.8,
        "explicacionPaso": "Como el Zener mantiene fijada la tensión en bornes de la carga en $V_Z$:\\n$I_L = \\frac{V_Z}{R_L} = \\frac{6.8\\text{ V}}{1000\\,\\Omega} = 6.8\\text{ mA}$."
      },
      {
        "id": "paso-2",
        "titulo": "2. Corriente por el diodo Zener",
        "pregunta": "Determine la corriente inversa de regulación $I_Z$ que absorbe el diodo Zener (en mA).",
        "pistas": [
          "Pista 1: Primero halle la corriente total $I_S$ que circula por la resistencia limitadora $R_S$: $I_S = (V_S - V_Z) / R_S$.",
          "Pista 2: Por LCK en el nodo de salida: $I_S = I_Z + I_L \\implies I_Z = I_S - I_L$.",
          "Pista 3: $I_S = (15 - 6.8) / 220 = 8.2 / 220 = 37.27\\text{ mA}$. Luego $I_Z = 37.27 - 6.8 = 30.47\\text{ mA}$."
        ],
        "explicacion": "Corriente total por el resistor limitador $R_S$:\\n$I_S = \\frac{V_S - V_Z}{R_S} = \\frac{15 - 6.8}{220} = \\frac{8.2}{220} \\approx 37.27\\text{ mA}$.\\nPor LCK: $I_Z = I_S - I_L = 37.27\\text{ mA} - 6.80\\text{ mA} = 30.47\\text{ mA}$.",
        "tipoRespuesta": "numerica",
        "unidad": "mA",
        "solucion": 30.47,
        "tolerancia": 0.05,
        "simbolo": "I_Z",
        "valorEsperado": 30.47,
        "explicacionPaso": "Corriente total por el resistor limitador $R_S$:\\n$I_S = \\frac{V_S - V_Z}{R_S} = \\frac{15 - 6.8}{220} = \\frac{8.2}{220} \\approx 37.27\\text{ mA}$.\\nPor LCK: $I_Z = I_S - I_L = 37.27\\text{ mA} - 6.80\\text{ mA} = 30.47\\text{ mA}$."
      }
    ]
