    "pasos": [
      {
        "id": "paso-1",
        "titulo": "1. Tensión continua media de salida",
        "pregunta": "Calcule la tensión continua media $V_{dc}$ (en Volts).",
        "pistas": [
          "Pista 1: Cada diodo conduce en su respectivo semiciclo con caída de un solo diodo: $V_{op} = 12 - 0.7 = 11.3\\text{ V}$.",
          "Pista 2: Al ser de onda completa: $V_{dc} = \\frac{2 V_{op}}{\\pi}$.",
          "Pista 3: $2 \\cdot 11.3 / \\pi \\approx 22.6 / 3.1416 = 7.19\\text{ V}$."
        ],
        "explicacion": "El pico en la carga es $V_{op} = V_p - V_D = 12 - 0.7 = 11.3\\text{ V}$. Para onda completa sin filtro: $V_{dc} = \\frac{2 V_{op}}{\\pi} = \\frac{22.6}{\\pi} \\approx 7.19\\text{ V}$.",
        "tipoRespuesta": "numerica",
        "unidad": "V",
        "solucion": 7.19,
        "tolerancia": 0.05,
        "simbolo": "V_{dc}",
        "valorEsperado": 7.19,
        "explicacionPaso": "El pico en la carga es $V_{op} = V_p - V_D = 12 - 0.7 = 11.3\\text{ V}$. Para onda completa sin filtro: $V_{dc} = \\frac{2 V_{op}}{\\pi} = \\frac{22.6}{\\pi} \\approx 7.19\\text{ V}$."
      },
      {
        "id": "paso-2",
        "titulo": "2. Tensión Inversa de Pico (PIV)",
        "pregunta": "Calcule el valor de PIV que debe soportar cada diodo en bloqueo inverso.",
        "pistas": [
          "Pista 1: En el rectificador con derivación central, cuando un diodo conduce su cátodo está en $+V_{op}$, mientras que el ánodo del otro diodo está en $-V_p$.",
          "Pista 2: $\\text{PIV} = 2 V_p - V_D$.",
          "Pista 3: $2(12) - 0.7 = 24 - 0.7 = 23.3\\text{ V}$."
        ],
        "explicacion": "En el pico del semiciclo positivo, el cátodo común está a $V_p - V_D = 11.3\\text{ V}$, mientras el bobinado inferior polariza el ánodo de D2 a $-V_p = -12\\text{ V}$. Por tanto: $\\text{PIV} = 11.3 - (-12) = 23.3\\text{ V}$ ($2 V_p - V_D$).",
        "tipoRespuesta": "numerica",
        "unidad": "V",
        "solucion": 23.3,
        "tolerancia": 0.05,
        "simbolo": "\\text{PIV}",
        "valorEsperado": 23.3,
        "explicacionPaso": "En el pico del semiciclo positivo, el cátodo común está a $V_p - V_D = 11.3\\text{ V}$, mientras el bobinado inferior polariza el ánodo de D2 a $-V_p = -12\\text{ V}$. Por tanto: $\\text{PIV} = 11.3 - (-12) = 23.3\\text{ V}$ ($2 V_p - V_D$)."
      }
    ]
